package com.vortex.a3.ui.icons

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

class IconLoadFailure(val iconName: String, causeDetail: Throwable? = null) :
    IllegalArgumentException("Solar icon failed to resolve: $iconName", causeDetail)

val SOLAR_ICON_ALLOWLIST: Set<String> = setOf("Add", "ArrowBack", "Battery2Bar", "BatteryAlert", "BatteryChargingFull", "BatteryFull", "BatteryStd", "Cast", "Check", "Close", "ContentPaste", "DarkMode", "Delete", "FileDownload", "Folder", "FolderBold", "Headphones", "Headset", "Home", "HomeBold", "Language", "Laptop", "LightMode", "Lock", "LockOpen", "Notifications", "NotificationsActive", "Power", "Settings", "SettingsBold", "Smartphone", "StickyNote2", "Suspend", "TouchApp")

fun assertSolarIconName(name: String) {
    if (!SOLAR_ICON_ALLOWLIST.contains(name)) throw IconLoadFailure(name)
}

internal class DuotonePath(val d: String, val alpha: Float = 1.0f)

private fun solarDuotone(name: String, vararg paths: DuotonePath): ImageVector {
    assertSolarIconName(name)
    val builder = ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
    )
    for (p in paths) {
        builder.addPath(
            pathData = addPathNodes(p.d),
            pathFillType = PathFillType.NonZero,
            stroke = SolidColor(Color.Black),
            strokeAlpha = p.alpha,
            strokeLineWidth = 1.7f,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        )
    }
    return builder.build()
}

private fun solarFilled(name: String, pathData: String): ImageVector {
    assertSolarIconName(name)
    val builder = ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
    )
    builder.addPath(
        pathData = addPathNodes(pathData),
        pathFillType = PathFillType.EvenOdd,
        fill = SolidColor(Color.Black),
    )
    return builder.build()
}

