    fun batteryIconFor(pct: Int?, charging: Boolean): ImageVector = when {
        charging -> BatteryChargingFull
        pct == null -> BatteryStd
        pct >= 80 -> BatteryFull
        pct >= 40 -> BatteryStd
        pct >= 15 -> Battery2Bar
        else -> BatteryAlert
    }

    fun lockIconFor(locked: Boolean): ImageVector = if (locked) Lock else LockOpen

    fun resolve(name: String): ImageVector = when (name) {
        "Add" -> Add
        "ArrowBack" -> ArrowBack
        "Battery2Bar" -> Battery2Bar
        "BatteryAlert" -> BatteryAlert
        "BatteryChargingFull" -> BatteryChargingFull
        "BatteryFull" -> BatteryFull
        "BatteryStd" -> BatteryStd
        "Cast" -> Cast
        "Check" -> Check
        "Close" -> Close
        "ContentPaste" -> ContentPaste
        "DarkMode" -> DarkMode
        "Delete" -> Delete
        "FileDownload" -> FileDownload
        "Folder" -> Folder
        "FolderBold" -> FolderBold
        "Headphones" -> Headphones
        "Headset" -> Headset
        "Home" -> Home
        "HomeBold" -> HomeBold
        "Language" -> Language
        "Laptop" -> Laptop
        "LightMode" -> LightMode
        "Lock" -> Lock
        "LockOpen" -> LockOpen
        "Notifications" -> Notifications
        "NotificationsActive" -> NotificationsActive
        "Power" -> Power
        "Settings" -> Settings
        "SettingsBold" -> SettingsBold
        "Smartphone" -> Smartphone
        "StickyNote2" -> StickyNote2
        "Suspend" -> Suspend
        "TouchApp" -> TouchApp
        else -> throw IconLoadFailure(name)
    }
}
